auto func (auto value){  
    int sum = 0;  
    for (int i = 0; i < value.size(); i++) {  
        sum += value[i];  
    }  
    return sum;  
}

auto func (auto value){  
    int sum = 0;  
    int product = 0;  
    for (int i = 0; i < 2; i++) {  
        sum += value;  
        product = sum * value;  
    }  
    return product;  
}

auto func (auto value){  
    int sum = 0;  
    for (int i = 0; i < value; i++)  
        sum += value;  
    return sum;  
}
